import zipfile, re
with zipfile.ZipFile('/root/training_feedback_template.hwpx', 'r') as z:
    for name in z.namelist():
        try:
            data = z.read(name).decode('utf-8', errors='replace')
            matches = re.findall(r'\{\{.*?\}\}', data)
            if matches:
                print(f'--- {name} ---')
                for m in matches:
                    print(f'  {m}')
        except:
            pass
"

